import{I as p,o as t,c as o,b6 as n,J as r,w as h,j as s,a as l}from"./chunks/framework.COUcLbTA.js";const k=JSON.parse('{"title":"用 Jobs to Be Done 找到用户真正想完成的事","description":"面向零基础读者的 Jobs to Be Done 入门文章。理解用户不是在买功能，而是在特定场景里“雇用”你的产品完成进展，并学会用 JTBD 拆解产品方向、访谈问题与 AI 提示词。","frontmatter":{"title":"用 Jobs to Be Done 找到用户真正想完成的事","description":"面向零基础读者的 Jobs to Be Done 入门文章。理解用户不是在买功能，而是在特定场景里“雇用”你的产品完成进展，并学会用 JTBD 拆解产品方向、访谈问题与 AI 提示词。"},"headers":[],"relativePath":"zh-cn/stage-1/appendix-jobs-to-be-done/index.md","filePath":"zh-cn/stage-1/appendix-jobs-to-be-done/index.md"}'),d={name:"zh-cn/stage-1/appendix-jobs-to-be-done/index.md"},_=Object.assign(d,{setup(c){const i="约 <strong>1.5 小时</strong>";return(b,a)=>{const e=p("ChapterIntroduction");return t(),o("div",null,[a[1]||(a[1]=n("",3)),r(e,{duration:i,tags:["JTBD","用户需求","产品思维","需求洞察"],coreOutput:"1 条更像真实需求的 JTBD 句子",expectedOutput:"能把模糊点子收成一个更具体的用户场景和 MVP 方向"},{default:h(()=>[...a[0]||(a[0]=[s("p",null,"很多人刚开始做产品时，最容易犯的一个错误是把注意力全部放在“我要做什么功能”上。看别人有智能分类，你也想加；看别人有自动总结，你也想接；看别人做了 Agent、多模态、工作流，你也觉得自己不能少。",-1),s("p",null,"但现实里，用户很少是因为“这个功能名字很酷”才决定用一个产品。他们更多是在某个具体时刻，想把一件事情推进下去，于是临时“雇用”了一个工具、一个服务，甚至一个人，来帮自己完成这一步。",-1),s("p",null,[l("这正是 "),s("strong",null,"Jobs to Be Done（JTBD）"),l(" 这套方法想提醒我们的事情："),s("strong",null,"用户不是在购买功能本身，而是在雇用某种解决方案，帮助自己完成一个进展。")],-1),s("p",null,"本篇文章会用尽量直白的语言，带你从零理解 JTBD，并把它变成你做 AI 应用时能直接拿来用的分析工具。",-1)])]),_:1}),a[2]||(a[2]=n("",148))])}}});export{k as __pageData,_ as default};
